insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('de90daf0-b4bc-520d-b3dc-fbff68f18ce6', 'Paróquia São José, a paróquia da Catedral Metropolitana de Fortaleza. A Igreja do Rosário, na Praça dos Leões, está fechada para reforma.', '{"https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-sao-jose/paroquias-da-regiao-sao-jose/paroquia-sao-jose-catedral-metropolitana-de-fortaleza/","https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-sao-jose/paroquias-da-regiao-sao-jose/paroquia-sao-jose-catedral-metropolitana-de-fortaleza/"}', 'alta'),
  ('95a97a96-1ef4-5669-a322-5e288b58db53', '', '{"https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-nossa-senhora-da-conceicao/paroquias-da-regiao/paroquia-nossa-senhora-do-brasil-messejana/","https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-nossa-senhora-da-conceicao/paroquias-da-regiao/paroquia-nossa-senhora-do-brasil-messejana/"}', 'alta'),
  ('9caace84-0fac-5631-9c78-1bc48d400d7a', '', '{"https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-nossa-senhora-da-conceicao/paroquias-da-regiao/area-pastoral-sao-joao-batista-messejana/","https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-nossa-senhora-da-conceicao/paroquias-da-regiao/area-pastoral-sao-joao-batista-messejana/"}', 'alta'),
  ('afa16cd0-bded-5f60-bf86-d49973c710b1', '', '{"https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-nossa-senhora-da-conceicao/paroquias-da-regiao/area-pastoral-sao-roque-conjunto-novo-mondubim/","https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-metropolitana-nossa-senhora-da-conceicao/paroquias-da-regiao/area-pastoral-sao-roque-conjunto-novo-mondubim/"}', 'alta'),
  ('b16c10ab-6e1f-5395-b611-3ca4e443cbd9', '', '{"https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-episcopal-metropolitana-bom-jesus-dos-aflitos/paroquias-da-regiao/paroquia-bom-jesus-dos-aflitos/","https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-episcopal-metropolitana-bom-jesus-dos-aflitos/paroquias-da-regiao/paroquia-bom-jesus-dos-aflitos/"}', 'alta'),
  ('af0e9065-76e1-50ae-8bbd-a9e78004743f', 'Fora do formato: Confissões: Terça-feira, após a missa das 19h, quarta, antes da missa das 19h e sexta, antes da missa das 19h.', '{"https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-episcopal-metropolitana-nossa-senhora-da-assuncao/paroquias-da-regiao/paroquia-cristo-redentor/","https://www.arquidiocesedefortaleza.org.br/arquidiocese/regioes/regiao-episcopal-metropolitana-nossa-senhora-da-assuncao/paroquias-da-regiao/paroquia-cristo-redentor/"}', 'alta'),
